/**
 * Slug for the first workspace. Reserved words and slugs shorter than the
 * minimum are never used; whatever is left falls back to `workspace`, and
 * `uniqueSlug` suffixes collisions the same way every other derived slug does.
 */
function workspaceSlug(displayName: string): string {
  const derived = slugify(displayName);
  const usable =
    derived.length >= SLUG_MIN_LENGTH && !isReservedSlug(derived) ? derived : "workspace";
  return uniqueSlug(usable, []);
}

/** `<name>'s workspace`, shortening the display name until the result fits. */
function workspaceName(displayName: string): string {
  let head = displayName;
  while (`${head}${WORKSPACE_SUFFIX}`.length > WORKSPACE_NAME_MAX && head.length > 0) {
    head = head.slice(0, -1);
  }
  return `${head}${WORKSPACE_SUFFIX}`;
}

